CREATE SCHEMA IF NOT EXISTS cadastre;CREATE SCHEMA IF NOT EXISTS registry;CREATE SCHEMA IF NOT EXISTS rural;CREATE SCHEMA IF NOT EXISTS infra;CREATE SCHEMA IF NOT EXISTS market;CREATE SCHEMA IF NOT EXISTS property360;CREATE SCHEMA IF NOT EXISTS condo;CREATE SCHEMA IF NOT EXISTS municipality;CREATE SCHEMA IF NOT EXISTS solar;CREATE SCHEMA IF NOT EXISTS aitec;CREATE SCHEMA IF NOT EXISTS analysis;
CREATE TABLE IF NOT EXISTS property360.property(id uuid PRIMARY KEY DEFAULT uuidv7(),tenant_id uuid NOT NULL,name text,municipality_ibge text,geom geometry(Geometry,4326),created_at timestamptz NOT NULL DEFAULT now());CREATE INDEX IF NOT EXISTS property360_property_geom_gix ON property360.property USING gist(geom);
CREATE TABLE IF NOT EXISTS rural.asset(id uuid PRIMARY KEY DEFAULT uuidv7(),tenant_id uuid,municipality_ibge text,name text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS rural.registry_record(id uuid PRIMARY KEY DEFAULT uuidv7(),asset_id uuid REFERENCES rural.asset(id),source_snapshot_id uuid REFERENCES source.snapshot(id),registry_type text NOT NULL,official_identifier text,attributes jsonb NOT NULL DEFAULT '{}'::jsonb,geom geometry(Geometry,4326),valid_from timestamptz,valid_to timestamptz);CREATE INDEX IF NOT EXISTS rural_registry_geom_gix ON rural.registry_record USING gist(geom);
CREATE TABLE IF NOT EXISTS condo.condominium(id uuid PRIMARY KEY DEFAULT uuidv7(),tenant_id uuid NOT NULL,name text NOT NULL,kind text NOT NULL,municipality_ibge text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS condo.document(id uuid PRIMARY KEY DEFAULT uuidv7(),tenant_id uuid NOT NULL,condominium_id uuid NOT NULL REFERENCES condo.condominium(id),kind text NOT NULL,title text NOT NULL,object_key text NOT NULL,sha256 text NOT NULL,visibility text NOT NULL DEFAULT 'PRIVATE',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS municipality.tenant(id uuid PRIMARY KEY DEFAULT uuidv7(),organization_id uuid NOT NULL REFERENCES iam.organization(id),municipality_ibge text NOT NULL UNIQUE,status text NOT NULL DEFAULT 'OFF',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS municipality.publication(id uuid PRIMARY KEY DEFAULT uuidv7(),municipality_tenant_id uuid NOT NULL REFERENCES municipality.tenant(id),snapshot_id uuid NOT NULL DEFAULT uuidv7(),status text NOT NULL DEFAULT 'DRAFT',published_at timestamptz,metadata jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS solar.project(id uuid PRIMARY KEY DEFAULT uuidv7(),tenant_id uuid NOT NULL,property_id uuid REFERENCES property360.property(id),status text NOT NULL DEFAULT 'DRAFT',input_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS aitec.project(id uuid PRIMARY KEY DEFAULT uuidv7(),tenant_id uuid NOT NULL,name text NOT NULL,property_id uuid REFERENCES property360.property(id),status text NOT NULL DEFAULT 'DRAFT',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS aitec.scenario(id uuid PRIMARY KEY DEFAULT uuidv7(),tenant_id uuid NOT NULL,project_id uuid NOT NULL REFERENCES aitec.project(id),constraint_snapshot_id uuid NOT NULL,solver_version text,status text NOT NULL DEFAULT 'QUEUED',metrics jsonb NOT NULL DEFAULT '{}'::jsonb,artifact_key text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS analysis.run(id uuid PRIMARY KEY DEFAULT uuidv7(),tenant_id uuid NOT NULL,property_id uuid REFERENCES property360.property(id),status text NOT NULL DEFAULT 'PENDING',base_date date NOT NULL DEFAULT current_date,input_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS analysis.finding(id uuid PRIMARY KEY DEFAULT uuidv7(),run_id uuid NOT NULL REFERENCES analysis.run(id),category text NOT NULL,status text NOT NULL,code text,title text NOT NULL,value jsonb,evidence_ids uuid[] NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
